const now = new Date();
const endDate = new Date(now);
endDate.setDate(endDate.getDate() - 1);
const startDate = new Date(now);
startDate.setDate(startDate.getDate() - 90);
const fmt = d => d.toISOString().split('T')[0];
return [{ json: { gsc_query_json: JSON.stringify({ startDate: fmt(startDate), endDate: fmt(endDate), dimensions: ['query'], rowLimit: 2500, dataState: 'final' }) } }];

const gscData = $('GSC Query').item.json;
const serpData = $('SerpAPI').item.json;
const blogResp = $('Leer Blog Sheet').first().json;
const blogVals = (blogResp.values || []).slice(1);
const existingKeywords = blogVals.map(row => (row[0] || '').toLowerCase().trim()).filter(k => k);

const gscQueries = (gscData.rows||[]).filter(r=>(r.impressions||0)>=3).sort((a,b)=>(b.impressions||0)-(a.impressions||0)).map(r=>'"'+r.keys[0]+'" (pos:'+(r.position||0).toFixed(1)+', imp:'+r.impressions+')').slice(0,60).join('\n');
const paa = (serpData.related_questions||[]).map(q=>q.question).join('\n');
const related = (serpData.related_searches||[]).map(s=>s.query).join('\n');

const systemMsg = 'Eres especialista en SEO y contenido editorial para Bigotes Caninos, blog de referencia sobre perros para familias caninas hispanohablantes. Generas ideas con demanda real y potencial de posicionamiento en Google. Voz Vet-Friend canino: cercana, científica digerible, energía exterior (parque, caminata, familia).';

const userMsg = 'Genera 15 ideas de contenido para BLOG.\n\n' +
  'KEYWORDS YA EN EL BLOG (NO repetir — verificar similitud ≥50% palabras):' + '\n' + (existingKeywords.slice(0,150).join('\n')||'(Sin datos)') +
  '\n\nQUERIES REALES GSC (últimos 90 días, ≥3 impresiones):' + '\n' + (gscQueries||'(Sin datos de GSC)') +
  '\n\nGENTE TAMBIÉN PREGUNTA (PAA):' + '\n' + (paa||'(Sin datos)') +
  '\n\nBÚSQUEDAS RELACIONADAS:' + '\n' + (related||'(Sin datos)') +
  '\n\nINSTRUCCIONES BLOG (15 ideas):' +
  '\n- Prioriza queries reales de GSC/PAA con oportunidad real' +
  '\n- Descarta cualquier keyword con ≥50% palabras significativas iguales a alguna existente' +
  '\n- Intención informacional o comercial, padres perrunos / familias caninas hispanohablantes' +
  '\n- Voz Vet-Friend canino: empática, rigor científico digerible, energía exterior y de acción (parque, caminata, juego, entrenamiento, familia)' +
  '\n- Diccionario de marca: usa "perros", "compañeros caninos", "familias caninas", "padres perrunos". NUNCA "mascota", "dueño", diminutivos infantiloides ni antropomorfización forzada' +
  '\n- COLOMBIA-FIRST QUOTA: MÍNIMO 6 de las 15 ideas DEBEN tener modificador colombiano explícito (Colombia, Bogotá, Medellín, Cali, Barranquilla, Cartagena, COP, pesos colombianos). Razón estratégica: en queries colombianos los competidores AIO son marketplaces/aseguradoras (Mercado Libre, Compensar, SURA), NO blogs caninos — ahí Bigotes Caninos gana rápido' +
  '\n- Ejemplos de keywords colombianas valiosas: "cuánto cuesta esterilizar un perro en Bogotá", "vacunación obligatoria perros Colombia precio", "veterinario domicilio perros Medellín precio", "guardería para perros Cali", "alimento Royal Canin perros Colombia precio", "dónde adoptar perro Bogotá", "adiestramiento canino Bogotá precio", "hospedaje perros Cartagena"' +
  '\n- Las otras 9 ideas restantes pueden ser hispanohablantes generales (México, España, Argentina) o sin modificador geográfico' +
  '\n- Prioridad ALTA: queries GSC con posición 11-30 + queries colombianas' +
  '\n- CRÍTICO anti-duplicados: NO propongas variantes con sufijos de keywords existentes. Si existe "X en perros", NO propongas "X en perros: síntomas", "qué hacer si X", "todo sobre X en perros". Tampoco con sinónimos: alimentación ≡ nutrición ≡ comida ≡ dieta; cuidados ≡ atención; mejor ≡ ideal ≡ óptimo. Antes de proponer, verifica que el TEMA no esté ya cubierto por una keyword existente en cualquier forma.' +
  '\n- Nichos válidos (ESTRICTO): Salud | Alimentación | Razas | Comportamiento. NO uses "Cuidados" ni "Mundo" ni "Entretenimiento".' +
  '\n\nRESPUESTA JSON ESTRICTO:' +
  '{"blog_ideas":[{"keyword":"...","nicho":"Salud|Alimentación|Razas|Comportamiento","pais":"Colombia|México|España|General","audiencia":"...","intencion":"Informacional|Comercial|Transaccional","prioridad":"Alta|Media|Baja","fuente":"GSC|PAA|Relacionadas|GPT"}]}';

const body = {model:'gpt-4o',response_format:{type:'json_object'},max_tokens:4000,messages:[{role:'system',content:systemMsg},{role:'user',content:userMsg}]};
return [{json:{gpt_body_json:JSON.stringify(body),existingKeywords } }];

const raw = $input.item.json.choices?.[0]?.message?.content || '';
const prev = $('Construir Prompt GPT').item.json;
const existingKeywords = prev.existingKeywords || [];

let ideas;
try { ideas = JSON.parse(raw); } catch(e) { throw new Error('Ideas parse error: ' + raw.substring(0,300)); }

const STOP = new Set(['de','la','el','en','y','para','un','una','con','del','los','las','que','perro','perros','mi','su','es','se','al','si','lo','le','tu','sus','o','u','sobre','por','desde','hasta','hacia','sin','muy','mas','menos','tambien','solo','este','esta','esto','estos','estas','les','ser','han','hay','han','sea','son','fue','era','tus']);

function strip(s){return (s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');}
function stem(t){return t.length>=5?t.slice(0,5):t;}
function tokList(s){return strip(s).split(/[^a-z0-9]+/).filter(t=>t.length>2&&!STOP.has(t)).map(stem);}
function toks(s){return new Set(tokList(s));}

function isDup(a,b){
  const wa=toks(a), wb=toks(b);
  if(!wa.size||!wb.size) return false;

  const ha=tokList(a), hb=tokList(b);
  if(ha.length>=2 && hb.length>=2 && ha[0]===hb[0] && ha[1]===hb[1]) return true;

  const inter=[...wa].filter(t=>wb.has(t)).length;
  const union=new Set([...wa,...wb]).size;
  const jacc=union?inter/union:0;
  const smaller=wa.size<=wb.size?wa:wb;
  const larger=wa.size<=wb.size?wb:wa;
  const cont=smaller.size?[...smaller].filter(t=>larger.has(t)).length/smaller.size:0;
  return jacc>=0.35 || cont>=0.8;
}

const HUB_MAP = {
  'Salud': { hub: 'Salud canina', slug: 'guia-salud-canina' },
  'Alimentación': { hub: 'Alimentación canina', slug: 'guia-alimentacion-perros' },
  'Alimentacion': { hub: 'Alimentación canina', slug: 'guia-alimentacion-perros' },
  'Razas': { hub: 'Razas de perros', slug: 'guia-razas-perros' },
  'Comportamiento': { hub: 'Comportamiento y Adiestramiento', slug: 'guia-comportamiento-canino' },
  'Adiestramiento': { hub: 'Comportamiento y Adiestramiento', slug: 'guia-comportamiento-canino' },
  'Educación': { hub: 'Comportamiento y Adiestramiento', slug: 'guia-comportamiento-canino' }
};
function mapHub(nicho){const k=(nicho||'').trim();return HUB_MAP[k]||HUB_MAP['Salud'];}

const rawBlog = ideas.blog_ideas || [];

const filteredBlog = rawBlog.filter(idea=>{
  const kw=(idea.keyword||'').trim();
  return kw && !existingKeywords.some(ex=>isDup(kw,ex));
});

const dedupedBlog = [];
for (const idea of filteredBlog){
  const kw=(idea.keyword||'').trim();
  const isDupInt = dedupedBlog.some(d=>isDup(kw, d.keyword||''));
  if(!isDupInt) dedupedBlog.push(idea);
}

const blogValues = dedupedBlog.map(idea=>{
  const hubInfo=mapHub(idea.nicho);
  return [
    idea.keyword||'',
    'Pendiente',
    idea.prioridad||'Media',
    idea.nicho||'',
    idea.pais||'General',
    idea.audiencia||'',
    idea.intencion||'Informacional',
    '', '', '', '', '', '',
    '', '', '', '',
    hubInfo.hub,
    hubInfo.slug
  ];
});

const blog_ideas_json = JSON.stringify({values:blogValues});
const blogVsSheet = rawBlog.length - filteredBlog.length;
const blogInternal = filteredBlog.length - dedupedBlog.length;

const hubCounts={};
for(const idea of dedupedBlog){const h=mapHub(idea.nicho).hub; hubCounts[h]=(hubCounts[h]||0)+1;}
const hubBreakdown=Object.entries(hubCounts).map(([h,c])=>'  • '+h+': '+c).join('\n');

const summary='\u{1F4A1} *Ideas generadas (BC)* ✅\n\n\u{1F4DD} *Blog:* '+dedupedBlog.length+' nuevas\n  • '+blogVsSheet+' descartadas vs Sheet\n  • '+blogInternal+' duplicados internos de GPT\n\n*Por hub:*\n'+(hubBreakdown||'  (sin ideas)')+'\n\n_Añadidas en Master Sheet canino con hub/cluster_parent auto-asignados._';

return [{ json:{ blog_ideas_json, blog_count: dedupedBlog.length, summary } }];
